{"name": "write_file", "arguments": {"file_path": "/app/reconcile.py", "content": "#!/usr/bin/env python3

import csv
from datetime import datetime, timezone, timedelta
from decimal import Decimal
import sys
import json

def parse_timestamp(ts_str):
    try:
        dt = datetime.fromisoformat(ts_str)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt
    except ValueError:
        return None

def is_valid_row(row):
    return all(field in row for field in ['tx_id', 'timestamp', 'amount', 'status']) and row['amount'].replace('.', '', 1).isdigit()

def reconcile_csv(file_path):
    valid_rows = {}
    with open(file_path, 'r') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            if not is_valid_row(row):
                continue
            tx_id = row['tx_id']
            ts = parse_timestamp(row['timestamp'])
            if ts is None:
                continue
            if tx_id in valid_rows and valid_rows[tx_id]['timestamp'] >= ts:
                continue
            valid_rows[tx_id] = row

    total_valid_amount = Decimal(0)
    valid_count = 0
    failed_count = 0
    for row in valid_rows.values():
        status = row['status']
        if status == 'SUCCESS':
            total_valid_amount += Decimal(row['amount'])
            valid_count += 1
        elif status == 'FAILED':
            failed_count += 1

    total_valid_amount = round(total_valid_amount, 2)

    output = {
        'total_valid_amount': total_valid_amount,
        'valid_count': valid_count,
        'failed_count': failed_count
    }

    return output

if __name__ == '__main__':
    if len(sys.argv) != 2:
        sys.stderr.write('Usage: python3 reconcile.py <path_to_csv_file>
')
        sys.exit(1)

    file_path = sys.argv[1]
    try:
        result = reconcile_csv(file_path)
        print(json.dumps(result))
    except Exception as e:
        sys.stderr.write(f'Error: {e}
')
        sys.exit(1)

